# prime_factors :: 12
def prime_factors(n):
    out = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            out.append(d)
            n //= d
        d += 1
    if n > 1: out.append(n)
    return out

if __name__ == '__main__':
    print(prime_factors(12))

